{
  "identity": {
    "name": "Acme",
    "description": "Acme pomaga founderom B2B SaaS ogarnąć chaos operacyjny, zanim skala sprzedaży rozjedzie się z delivery. Od 2019 robimy audyty procesów w zespołach 8–40 osób w Polsce i CEE — bez wdrożenia w cenie, z listą usprawnień do samodzielnego pociągnięcia."
  },
  "offer": {
    "items": [
      {
        "name": "Audyt procesów operacyjnych",
        "benefit": [
          "Średnio 6 godzin tygodniowo odzyskane u klientów po wdrożeniu rekomendacji",
          "Mapa wąskich gardeł w 10 dni roboczych",
          "Jedna lista priorytetów zamiast dwudziestu równoległych inicjatyw"
        ],
        "description": "Wywiady z founderem i 3–5 osobami z ops/CS/product, mapa as-is, lista usprawnień z szacunkiem wysiłku. Bez implementacji w cenie audytu."
      },
      {
        "name": "Sesja priorytetyzacji Q+1",
        "benefit": [
          "Trzy tematy na kolejny kwartał, reszta świadomie odłożona"
        ],
        "description": "Południowa jednodniówka po audycie: wybór trzech tematów na najbliższy kwartał i właścicieli. Opcja, nie pakiet obowiązkowy."
      }
    ]
  },
  "voice": {
    "weDo": "konkret, liczby z audytu, język founderski, krótkie zdania, bez slajdowego entuzjazmu",
    "weDont": "żargon, puste obietnice wzrostu MRR, porównywanie z konkurencją, korpo-ogólniki w stylu synergia i transformacja"
  },
  "cta": {
    "items": [
      { "label": "Napisz do nas", "target": "/kontakt" },
      { "label": "Umów 20 minut na wstępny zakres audytu", "target": "/kontakt" }
    ]
  },
  "audience": {
    "profiles": [
      {
        "description": "Founder SaaS B2B, zespół 8–40 osób, po seedzie lub serii A. Sprzedaż idzie, a onboarding, CS i handoff między product a ops się sypią. Szuka przeglądu procesów, nie kolejnego narzędzia."
      }
    ]
  },
  "extras": {
    "hashtags": ["#acme", "#saasops", "#founders"],
    "performanceNotes": "Klienci po audycie najczęściej tną tygodniowy chaos spotkań i ręcznych handoffów; typowy trop to 6 godzin odzyskane tygodniowo, nie skok MRR."
  }
}
